288: /**
289:  * v1.5.13: KONSERVO DETEKCIJA is teksto (kategorija + pavadinimas).
290:  * Naudojama PRIES sukurima (block_zb_create, is $data) ir PO (initial_import).
291:  */
292: function petshop_xml_text_is_konservas( string $category, string $name ): bool {
293:     $cat = mb_strtolower( $category );
294:     if ( mb_strpos( $cat, 'konserv' ) !== false ) {
295:         return true;
296:     }
297:     $title = mb_strtolower( $name );
298:     if ( preg_match( '/konserv|\bwet\b|pate|paštet|pastet|mousse|pouch|flakes|chunks|gabal.*padaž|drebučiuose|drebuciuose/iu', $title ) ) {
299:         return true;
300:     }
301:     return false;
302: }
