304: /**
305:  * v1.5.13: KONSERVO DETEKCIJA pagal post_id (WC kategorija + meta + title).
306:  */
307: function petshop_xml_is_konservas( int $post_id ): bool {
308:     $terms   = wp_get_object_terms( $post_id, 'product_cat', [ 'fields' => 'names' ] );
309:     $cat_str = ( ! is_wp_error( $terms ) && $terms ) ? implode( ' ', $terms ) : '';
310:     $zbcat   = (string) get_post_meta( $post_id, '_zb_category', true );
311:     $title   = (string) get_the_title( $post_id );
312:     return petshop_xml_text_is_konservas( $cat_str . ' ' . $zbcat, $title );
313: }
