315: /**
316:  * v1.5.13: ZB SKIP-BEFORE-CREATE — sprendzia PRIES sukurima (tik ZB Import #2).
317:  *
318:  * Hook: wp_all_import_is_post_to_create (analogiska VF v1.5.12).
319:  *
320:  * Logika (ZB $data raktai patvirtinti diagnostika 2026-06-14):
321:  *   - Konservas (category ARBA name)              -> LEISTI (initial_import -> draft)
322:  *   - qty <= 0                                     -> LEISTI (initial_import -> draft)
323:  *   - price < MIN_COST IR NE konservas IR qty>0    -> NEKURTI (aksesuaras, kartele)
324:  *   - kitaip                                       -> LEISTI (normali preke)
325:  *
326:  * Fail-safe = LEISTI. Tik gryna logika (jokiu DB uzklausu) -> nestabdo importo.
327:  * ESME: aksesuarai NET NESUKURIAMI -> nuotrauka neparsisiunciama -> 0 trash.
328:  */
329: add_filter( 'wp_all_import_is_post_to_create', 'petshop_xml_block_zb_create', 10, 3 );
330: 
331: function petshop_xml_block_zb_create( $continue_import, $data, $import_id ) {
332: 
333:     // Saugiklis: tik ZB importas #2
334:     if ( ! in_array( (int) $import_id, PETSHOP_XML_ZB_IMPORT_IDS, true ) ) {
335:         return $continue_import;
336:     }
337:     // Saugiklis: $data turi buti masyvas
338:     if ( ! is_array( $data ) ) {
339:         return $continue_import;
340:     }
341: 
342:     $name     = (string) ( $data['name'] ?? '' );
343:     $category = (string) ( $data['category'] ?? '' );
344:     $brand    = (string) ( $data['brand'] ?? '' );
345:     $price    = isset( $data['price'] ) ? (float) str_replace( ',', '.', (string) $data['price'] ) : 0.0;
346:     $qty      = isset( $data['qty'] )   ? (int) $data['qty'] : 0;
347: 
348:     // Fail-safe: jei tuscia esmine info -> leisti (neblokuojam aklai)
349:     if ( $name === '' && $category === '' ) {
350:         return $continue_import;
351:     }
352: 
353:     // v1.5.17: EXCLUDED BRAND -> NEKURTI (prie vartu).
354:     //
355:     //   Tokie brandai (Hau&Miau, Bioveterinary ir kt.) pas mus JAU egzistuoja
356:     //   kaip Legacy prekes (su istorija, kaina, SEO). ZB juos irgi siuncia, bet
357:     //   jie NETURI patekti is ZB — turi but blokuojami "prie vartu", o ne
358:     //   sukuriami ir tik po to metami i draft (excluded_brand). Anksciau
359:     //   is_excluded_brand() veike tik PO sukurimo (initial_import) -> preke buvo
360:     //   sukuriama, parsisiusta nuotrauka, tik po to draft -> siuksles + kreditai.
361:     //   Dabar blokuojam PRIES sukurima (kaip konservas/qty/aksesuaras patikros).
362:     //
363:     //   Brandas tikrinamas is $data['brand']; jei tuscias -> is name (fallback),
364:     //   nes is_excluded_brand() moka atpazinti pagal pavadinima.
365:     if ( class_exists( 'Petshop_Import_Rules' ) ) {
366:         $rules_gate   = new Petshop_Import_Rules();
367:         $brand_check  = $brand !== '' ? $brand : $name;
368:         $brand_check  = trim( html_entity_decode( $brand_check, ENT_QUOTES | ENT_HTML5, 'UTF-8' ) );
369:         if ( $brand_check !== '' && $rules_gate->is_excluded_brand( $brand_check ) ) {
370:             petshop_xml_log_structured( [
371:                 'action'    => 'ZB-BLOCK-CREATE',
372:                 'name'      => mb_substr( $name, 0, 60 ),
373:                 'brand'     => mb_substr( $brand_check, 0, 40 ),
374:                 'reason'    => 'excluded_brand',
375:                 'import_id' => $import_id,
376:                 'note'      => 'ZB create prevented (excluded brand, exists as Legacy) at the gate (v1.5.17)',
377:             ] );
378:             return false; // BLOKUOTI kurima
379:         }
380:     }
381: 
382:     // Konservas -> LEISTI (taps draft per initial_import, box rinkiniams)
383:     if ( petshop_xml_text_is_konservas( $category, $name ) ) {
384:         return $continue_import;
385:     }
386: 
387:     // v1.5.15: NAUJA preke qty <= 0 -> NEKURTI.
388:     //
389:     //   Priezastis (savininko sprendimas 2026-06-14): nauja preke be likucio
390:     //   neturi SEO istorijos ir nera paklausos (niekas jos nemate). Jos kurti
391:     //   neverta — tik kauptu siuksles. Jei ZB veliau atsius ja SU likuciu
392:     //   (qty>0), ji bus sukurta tada (publish). Tai automatinis "blokavimas":
393:     //   nauja qty=0 nekuriama, bet grizus su likuciu — kuriama.
394:     //
395:     //   ESAMOS prekes qty=0 tvarkomos initial_import() (buvusi publish ->
396:     //   lieka matoma SEO+paklausai; gimusi draft -> 30 d. cleanup).
397:     if ( $qty <= 0 ) {
398:         petshop_xml_log_structured( [
399:             'action'    => 'ZB-BLOCK-CREATE',
400:             'name'      => mb_substr( $name, 0, 60 ),
401:             'category'  => mb_substr( $category, 0, 60 ),
402:             'price'     => $price,
403:             'qty'       => $qty,
404:             'reason'    => 'qty_zero_new_no_history',
405:             'import_id' => $import_id,
406:             'note'      => 'ZB create prevented (new qty=0, no SEO/demand) before image download (v1.5.15)',
407:         ] );
408:         return false; // BLOKUOTI kurima
409:     }
410: 
411:     // Aksesuaras: pigus (< kartele) IR NE konservas IR turi likuti -> NEKURTI
412:     if ( $price > 0 && $price < PETSHOP_XML_ZB_MIN_COST ) {
413:         petshop_xml_log_structured( [
414:             'action'    => 'ZB-BLOCK-CREATE',
415:             'name'      => mb_substr( $name, 0, 60 ),
416:             'category'  => mb_substr( $category, 0, 60 ),
417:             'price'     => $price,
418:             'qty'       => $qty,
419:             'reason'    => 'cost_below_minimum_accessory',
420:             'import_id' => $import_id,
421:             'note'      => 'ZB create prevented (accessory below min cost) before image download (v1.5.13)',
422:         ] );
423:         return false; // BLOKUOTI kurima
424:     }
425: 
426:     // Praeina -> leisti kurti normaliai
427:     return $continue_import;
428: }
